import type jsPDF from "jspdf";

// Same logo as public/maruthi-logo.png, inlined so jsPDF can draw it synchronously.
const LOGO_DATA_URL =
  "data:image/png;base64,";
const LOGO_ASPECT = 795 / 273;

export type PdfLetterheadOptions = {
  margin: number;
  title: string;
  /** Document number shown top-right. */
  refId?: string;
  /** Pre-formatted date shown under the document number. */
  date?: string;
};

/**
 * Draws the shared MARUTHI IT SERVICES letterhead (logo, doc no/date, blue rule,
 * centered title) at the top of the current page. Returns the y position to continue from.
 */
export function drawPdfLetterhead(
  doc: jsPDF,
  { margin, title, refId, date }: PdfLetterheadOptions,
): number {
  const pageWidth = doc.internal.pageSize.getWidth();
  const logoWidth = 62;
  const logoHeight = logoWidth / LOGO_ASPECT;
  let y = margin;

  doc.addImage(LOGO_DATA_URL, "PNG", margin - 2, y, logoWidth, logoHeight);

  doc.setTextColor(15, 23, 42);
  if (refId) {
    doc.setFont("courier", "bold");
    doc.setFontSize(10);
    doc.text(refId, pageWidth - margin, y + 4, { align: "right" });
  }
  if (date) {
    doc.setFont("helvetica", "normal");
    doc.setFontSize(9);
    doc.setTextColor(51, 65, 85);
    doc.text(date, pageWidth - margin, y + 9, { align: "right" });
  }

  y += logoHeight + 2;
  doc.setFillColor(37, 99, 235);
  doc.rect(margin, y, pageWidth - margin * 2, 0.9, "F");

  y += 9;
  doc.setFont("helvetica", "bold");
  doc.setFontSize(12.5);
  doc.setTextColor(15, 23, 42);
  doc.text(title.toUpperCase(), pageWidth / 2, y, {
    align: "center",
    charSpace: 1.2,
  });

  return y + 8;
}
